  return (
    <div className="px-4 pb-6 max-w-2xl mx-auto w-full space-y-4">
      <div className="card">
        <div className="p-5">
          <h2 className="text-sm font-semibold text-slate-700 mb-3">Accounts</h2>

          {error && <p className="auth-error-text mb-2">{error}</p>}
          {status && <p className="auth-success-text mb-2">{status}</p>}
        </div>

        {accounts.length === 0 ? (
          <p className="auth-small-note px-5 pb-5">No accounts yet.</p>
        ) : (
          <div className="card-divide">
            {accounts.map((account) => (
              <div key={account.id} className="row-primary">
                <div className="flex min-w-0 items-center gap-3">
                  <div className="avatar avatar-sm avatar-neutral">{account.name?.charAt(0)}</div>
                  <div className="min-w-0">
                    <div className="truncate text-sm font-medium text-slate-800">{account.name}</div>
                    <div className="truncate text-xs text-slate-500">{account.email}</div>
                  </div>
                </div>
                <div className="flex shrink-0 items-center gap-1">
                  <span className={`pill ${account.role === 'staff' ? 'pill-pending' : 'pill-info'}`}>{account.role}</span>
                  <button className="btn btn-sm btn-ghost" type="button" onClick={() => handleSelect(account)}>Edit</button>
                  <button className="btn btn-sm btn-danger" type="button" onClick={() => handleDelete(account.id)}>Delete</button>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      <div className="card-pad">
        <h2 className="text-sm font-semibold text-slate-700 mb-3">{selected ? 'Edit Account' : 'Create Account'}</h2>

        <form onSubmit={selected ? handleUpdate : handleCreate} className="space-y-3">
          <label className="field">
            Full Name
            <input className="input" value={form.name} onChange={(event) => setForm({ ...form, name: event.target.value })} required />
          </label>
          <label className="field">
            Email
            <input type="email" className="input" value={form.email} onChange={(event) => setForm({ ...form, email: event.target.value })} required />
          </label>
          <label className="field">
            Password
            <input type="password" className="input" value={form.password} onChange={(event) => setForm({ ...form, password: event.target.value })} placeholder={selected ? 'Leave blank to keep current' : ''} required={!selected} />
          </label>
          <label className="field">
            Role
            <select className="select" value={form.role} onChange={(event) => setForm({ ...form, role: event.target.value })}>
              <option value="participant">Participant</option>
              <option value="staff">Staff</option>
            </select>
          </label>

          {!selected && (
            <fieldset className="auth-fieldset">
              <legend>Face Registration <span className="text-red-600">*</span></legend>
              <p className="auth-small-note mt-1">Attach a face image for facial recognition - required</p>

              <div className="face-source-tabs">
                {['url', 'file', 'camera'].map((src) => (
                  <button
                    key={src}
                    type="button"
                    className={`face-source-btn ${faceSource === src ? 'active' : ''}`}
                    onClick={() => {
                      if (faceSource === src) { clearFace(); return; }
                      clearFace();
                      setFaceSource(src);
                      if (src === 'camera') startCamera();
                    }}
                  >
                    {src === 'url' ? 'URL' : src === 'file' ? 'Upload' : 'Camera'}
                  </button>
                ))}
              </div>

              {faceSource === 'url' && (
                <div className="face-url-row">
                  <input
                    type="url"
                    placeholder="https://example.com/face.jpg"
                    className="face-url-input"
                    onKeyDown={(e) => { if (e.key === 'Enter') { e.preventDefault(); handleUrlImage(e.target.value); } }}
                  />
                  <button type="button" className="btn btn-sm btn-secondary" onClick={(e) => handleUrlImage(e.target.closest('.face-url-row').querySelector('input').value)}>Load</button>
                </div>
              )}

              {faceSource === 'file' && (
                <input type="file" accept="image/*" onChange={(e) => { const f = e.target.files[0]; if (f) handleFileImage(f); }} className="face-file-input" />
              )}

              {faceSource === 'camera' && (
                <div className="face-camera-box">
                  <video ref={videoRef} className="face-camera-video" playsInline muted />
                  <canvas ref={canvasRef} className="hidden" />
                  {cameraActive && (
                    <button type="button" className="btn btn-primary btn-sm" onClick={captureFromCamera}>Capture</button>
                  )}
                </div>
              )}

              {facePreview && (
                <div className="face-preview-row">
                  <img src={facePreview} alt="Face preview" className="face-preview-img" />
                  <button type="button" className="btn btn-sm btn-danger" onClick={clearFace}>Remove</button>
                </div>
              )}
            </fieldset>
          )}

          <button className="btn btn-primary btn-block" type="submit" disabled={uploadingFace || (!selected && !faceImageBase64)}>
            {uploadingFace ? 'Uploading face...' : selected ? 'Update Account' : 'Create Account'}
          </button>
          {selected && (
            <button type="button" className="btn btn-ghost btn-block" onClick={handleCancelEdit}>Cancel</button>
          )}
        </form>
      </div>
    </div>
  );
}

